    public static void ClassInit(TestContext context)
    {
        _fixture = new DbFixture();
    }

    [ClassCleanup]
    public static void ClassCleanup()
    {
        _fixture.Dispose();
    }

    [TestMethod]
    public void Fixture_HasConnectionString()
    {
        Assert.IsNotNull(_fixture.ConnectionString);
    }
}

